mapper.update:
UPDATE refund_funding_allocation SET status = 'PROCESSING', version = version + 1,
    updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = #{id} AND status IN ('PENDING', 'FAILED') AND deleted = FALSE

UPDATE refund_funding_allocation SET status = 'PENDING', failure_code = NULL, failure_message = NULL,
    version = version + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = #{id} AND status = 'FAILED' AND deleted = FALSE
